class Solution {
    public int strStr(String haystack, String needle) {
        int[] lps = new int[needle.length()];
        int prefixLength = 0;
        int patternIndex = 1;

        while (patternIndex < needle.length()) {
            if (needle.charAt(patternIndex) == needle.charAt(prefixLength)) {
                lps[patternIndex] = ++prefixLength;
                patternIndex++;
            } else if (prefixLength > 0) {
                prefixLength = lps[prefixLength - 1];
            } else {
                lps[patternIndex] = 0;
                patternIndex++;
            }
        }

        int textIndex = 0;
        int matched = 0;
        while (textIndex < haystack.length()) {
            if (haystack.charAt(textIndex) == needle.charAt(matched)) {
                textIndex++;
                matched++;
                if (matched == needle.length()) {
                    return textIndex - matched;
                }
            } else if (matched > 0) {
                matched = lps[matched - 1];
            } else {
                textIndex++;
            }
        }
        return -1;
    }
}
